const focusListeners = new Set<(projectId: string) => void>();
export function publishProjectFocus(projectId: string): void { for (const listener of focusListeners) listener(projectId); }
export function subscribeProjectFocus(listener: (projectId: string) => void): () => void {
  focusListeners.add(listener);
  return () => { focusListeners.delete(listener); };
}
